  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  });
  const page = await browser.newPage();
  const url = 'file://' + path.resolve(process.argv[2]);
  await page.goto(url, { waitUntil: 'networkidle0' });
  // Allow Babel/React render
  await new Promise(r => setTimeout(r, 1500));

  const html = await page.content();
  console.log('--- rendered length:', html.length);
  console.log('--- root has child:', /id="root"><[^>]/.test(html) || /id="root"\s*>\s*<\w/.test(html));

  // Test 1: collapsed state
  let results = await new AxePuppeteer(page).withTags(['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice']).analyze();
  console.log('\n=== COLLAPSED VIOLATIONS ===');
  for (const v of results.violations) {
    console.log(`[${v.impact}] ${v.id}: ${v.help}`);
    for (const n of v.nodes) console.log('   target:', n.target, '\n   ', n.failureSummary?.split('\n').join(' | '));
  }

  // Expand all triggers
  await page.$$eval('button[aria-expanded]', btns => btns.forEach(b => b.click()));
